<div class="split-panels"><section class="panel"><div class="panel-heading"><div><h2>Role matrix</h2><p>Choose each group and assign explicit capabilities.</p></div></div><div class="role-matrix"><?php foreach($groups as $g):?><div class="role-block"><h3><?= esc($g['name']) ?> <?php if((int)$g['id']===1):?><span class="pill">PROTECTED</span><?php endif;?></h3><small><?= esc($g['description']??'') ?></small><div class="permissions-grid"><?php foreach($permissions as $p):if($p['code']==='*'&&(int)$g['id']!==1)continue;$isAssigned=false;foreach($assigned as $a){if((int)$a['group_id']===(int)$g['id']&&(int)$a['permission_id']===(int)$p['id']){$isAssigned=true;break;}}?><form action="/admin/groups/permission" method="post" class="permission-item"><input type="hidden" name="_csrf" value="<?= esc(\Brightery\Core\App::get()->service(\Brightery\Core\Security::class)->csrf()) ?>"><input type="hidden" name="group_id" value="<?= (int)$g['id'] ?>"><input type="hidden" name="permission_id" value="<?= (int)$p['id'] ?>"><input type="hidden" name="enabled" value="<?= $isAssigned?'0':'1' ?>"><button type="submit" class="permission-toggle <?= $isAssigned?'selected':'' ?>" <?= (int)$g['id']===1?'disabled':'' ?> title="Toggle permission"><span><?= $isAssigned?'✓':'+' ?></span> <?= esc($p['code']) ?></button></form><?php endforeach;?></div></div><?php endforeach;?></div></section><section class="panel"><div class="panel-heading"><h2>New group</h2></div><form action="/admin/groups/create" method="post" class="form-stack"><input type="hidden" name="_csrf" value="<?= esc(\Brightery\Core\App::get()->service(\Brightery\Core\Security::class)->csrf()) ?>"><label class="bf-field"><span>Group name</span><input name="name" required maxlength="120" placeholder="Content Manager"></label><label class="bf-field"><span>Description</span><textarea name="description" rows="4" placeholder="What this group is responsible for"></textarea></label><button type="submit" class="btn btn-primary">Create group →</button></form><div class="hint"><b>Security model</b> Deny by default. Permissions are granted via group membership; Super Admin is protected.</div></section></div>
